package binding

import (
	"errors"
	"fmt"
	"io"
	"reflect"
	"strconv"
	"strings"
	"time"
)

var (
	errUnknownType = errors.New("unknown type")

	// ErrConvertMapStringSlice can not convert to map[string][]string
	ErrConvertMapStringSlice = errors.New("can not convert to map slices of strings")

	// ErrConvertToMapString can not convert to map[string]string
	ErrConvertToMapString = errors.New("can not convert to map of strings")
)

func mapURI(ptr any, m map[string][]string) error {
	return mapFormByTag(ptr, m, "uri")
}

func mapForm(ptr any, form map[string][]string) error {
	return mapFormByTag(ptr, form, "form")
}

func MapFormWithTag(ptr any, form map[string][]string, tag string) error {
	return mapFormByTag(ptr, form, tag)
}

var emptyField = reflect.StructField{}

func mapFormByTag(ptr any, form map[string][]string, tag string) error {
	// Check if ptr is a map
	ptrVal := reflect.ValueOf(ptr)
	var pointed any
	if ptrVal.Kind() == reflect.Ptr {
		ptrVal = ptrVal.Elem()
		pointed = ptrVal.Interface()
	}
	if ptrVal.Kind() == reflect.Map &&
		ptrVal.Type().Key().Kind() == reflect.String {
		if pointed != nil {
			ptr = pointed
		}
		return setFormMap(ptr, form)
	}

	return mappingByPtr(ptr, formSource(form), tag)
}

// setter tries to set value on a walking by fields of a struct
type setter interface {
	TrySet(value reflect.Value, field reflect.StructField, key string, opt setOptions) (isSet bool, err error)
}

type formSource map[string][]string

var _ setter = formSource(nil)

// TrySet tries to set a value by request's form source (like map[string][]string)
func (form formSource) TrySet(value reflect.Value, field reflect.StructField, tagValue string, opt setOptions) (isSet bool, err error) {
	return setByForm(value, field, form, tagValue, opt)
}

func mappingByPtr(ptr any, setter setter, tag string) error {
	_, err := mapping(reflect.ValueOf(ptr), emptyField, setter, tag)
	return err
}

func mapping(value reflect.Value, field reflect.StructField, setter setter, tag string) (bool, error) {
	if field.Tag.Get(tag) == "-" { // just ignoring this field
		return false, nil
	}

	vKind := value.Kind()

	if vKind == reflect.Ptr {
		var isNew bool
		vPtr := value
		if value.IsNil() {
			isNew = true
			vPtr = reflect.New(value.Type().Elem())
		}
		isSet, err := mapping(vPtr.Elem(), field, setter, tag)
		if err != nil {
			return false, err
		}
		if isNew && isSet {
			value.Set(vPtr)
		}
		return isSet, nil
	}

	if vKind != reflect.Struct || !field.Anonymous {
		ok, err := tryToSetValue(value, field, setter, tag)
		if err != nil {
			return false, err
		}
		if ok {
			return true, nil
		}
	}

	if vKind == reflect.Struct {
		tValue := value.Type()

		var isSet bool
		for i := 0; i < value.NumField(); i++ {
			sf := tValue.Field(i)
			if sf.PkgPath != "" && !sf.Anonymous { // unexported
				continue
			}
			ok, err := mapping(value.Field(i), sf, setter, tag)
			if err != nil {
				return false, err
			}
			isSet = isSet || ok
		}
		return isSet, nil
	}
	return false, nil
}

type setOptions struct {
	isDefaultExists bool
	defaultValue    string
}

func tryToSetValue(value reflect.Value, field reflect.StructField, setter setter, tag string) (bool, error) {
	var tagValue string
	var setOpt setOptions

	tagValue = field.Tag.Get(tag)
	tagValue, opts := head(tagValue, ",")

	if tagValue == "" { // default value is FieldName
		tagValue = field.Name
	}
	if tagValue == "" { // when field is "emptyField" variable
		return false, nil
	}

	var opt string
	for len(opts) > 0 {
		opt, opts = head(opts, ",")

		if k, v := head(opt, "="); k == "default" {
			setOpt.isDefaultExists = true
			setOpt.defaultValue = v
		}
	}

	return setter.TrySet(value, field, tagValue, setOpt)
}

func setByForm(value reflect.Value, field reflect.StructField, form map[string][]string, tagValue string, opt setOptions) (isSet bool, err error) {
	vs, ok := form[tagValue]
	if !ok && !opt.isDefaultExists {
		return false, nil
	}

	switch value.Kind() {
	case reflect.Slice:
		if !ok {
			vs = []string{opt.defaultValue}
		}
		return true, setSlice(vs, value, field)
	case reflect.Array:
		if !ok {
			vs = []string{opt.defaultValue}
		}
		if len(vs) != value.Len() {
			return false, fmt.Errorf("%q is not valid value for %s", vs, value.Type().String())
		}
		return true, setArray(vs, value, field)
	default:
		var val string
		if !ok {
			val = opt.defaultValue
		}

		if len(vs) > 0 {
			val = vs[0]
		}
		return true, setWithProperType(val, value, field)
	}
}

func setWithProperType(val string, value reflect.Value, field reflect.StructField) error {
	if value.IsValid() {
		if _, isFileHeader := fileHeaderFromValue(value); isFileHeader {
			if value.Kind() == reflect.Ptr {
				if !value.Elem().IsValid() {
					value.Set(reflect.New(value.Type().Elem()))
				}
				if value.Elem().IsValid() {
					return setWithProperType(val, value.Elem(), field)
				}
				return errUnknownType
			}
			if value.Kind() == reflect.Struct {
				if value.CanAddr() {
					dest := value.Addr().Interface()
					if dest != nil {
						if len(val) == 0 {
							err := decodeFormJSON(val, dest)
							if err != nil {
								if errors.Is(err, io.ErrUnexpectedEOF) {
									return err
								}
								return err
							}
							return nil
						}
						err := decodeFormJSON(val, dest)
						if err != nil {
							return err
						}
						return nil
					}
				}
				return decodeFormJSON(val, value.Addr().Interface())
			}
		}
		switch value.Kind() {
		case reflect.Int:
			rawInt := val
			if rawInt == "" {
				rawInt = "0"
			}
			parsedInt, errInt := strconv.ParseInt(rawInt, 10, 0)
			if errInt != nil {
				return errInt
			}
			value.SetInt(parsedInt)
			return nil
		case reflect.Int8:
			rawInt8 := val
			if rawInt8 == "" {
				rawInt8 = "0"
			}
			parsedInt8, errInt8 := strconv.ParseInt(rawInt8, 10, 8)
			if errInt8 != nil {
				return errInt8
			}
			value.SetInt(parsedInt8)
			return nil
		case reflect.Int16:
			rawInt16 := val
			if rawInt16 == "" {
				rawInt16 = "0"
			}
			parsedInt16, errInt16 := strconv.ParseInt(rawInt16, 10, 16)
			if errInt16 != nil {
				return errInt16
			}
			value.SetInt(parsedInt16)
			return nil
		case reflect.Int32:
			rawInt32 := val
			if rawInt32 == "" {
				rawInt32 = "0"
			}
			parsedInt32, errInt32 := strconv.ParseInt(rawInt32, 10, 32)
			if errInt32 != nil {
				return errInt32
			}
			value.SetInt(parsedInt32)
			return nil
		case reflect.Int64:
			switch value.Interface().(type) {
			case time.Duration:
				parsedDuration, durationErr := time.ParseDuration(val)
				if durationErr != nil {
					return durationErr
				}
				value.Set(reflect.ValueOf(parsedDuration))
				return nil
			}
			rawInt64 := val
			if rawInt64 == "" {
				rawInt64 = "0"
			}
			parsedInt64, errInt64 := strconv.ParseInt(rawInt64, 10, 64)
			if errInt64 != nil {
				return errInt64
			}
			value.SetInt(parsedInt64)
			return nil
		case reflect.Uint:
			rawUint := val
			if rawUint == "" {
				rawUint = "0"
			}
			parsedUint, errUint := strconv.ParseUint(rawUint, 10, 0)
			if errUint != nil {
				return errUint
			}
			value.SetUint(parsedUint)
			return nil
		case reflect.Uint8:
			rawUint8 := val
			if rawUint8 == "" {
				rawUint8 = "0"
			}
			parsedUint8, errUint8 := strconv.ParseUint(rawUint8, 10, 8)
			if errUint8 != nil {
				return errUint8
			}
			value.SetUint(parsedUint8)
			return nil
		case reflect.Uint16:
			rawUint16 := val
			if rawUint16 == "" {
				rawUint16 = "0"
			}
			parsedUint16, errUint16 := strconv.ParseUint(rawUint16, 10, 16)
			if errUint16 != nil {
				return errUint16
			}
			value.SetUint(parsedUint16)
			return nil
		case reflect.Uint32:
			rawUint32 := val
			if rawUint32 == "" {
				rawUint32 = "0"
			}
			parsedUint32, errUint32 := strconv.ParseUint(rawUint32, 10, 32)
			if errUint32 != nil {
				return errUint32
			}
			value.SetUint(parsedUint32)
			return nil
		case reflect.Uint64:
			rawUint64 := val
			if rawUint64 == "" {
				rawUint64 = "0"
			}
			parsedUint64, errUint64 := strconv.ParseUint(rawUint64, 10, 64)
			if errUint64 != nil {
				return errUint64
			}
			value.SetUint(parsedUint64)
			return nil
		case reflect.Bool:
			rawBool := val
			if rawBool == "" {
				rawBool = "false"
			}
			parsedBool, errBool := strconv.ParseBool(rawBool)
			if errBool != nil {
				return errBool
			}
			value.SetBool(parsedBool)
			return nil
		case reflect.Float32:
			rawFloat32 := val
			if rawFloat32 == "" {
				rawFloat32 = "0.0"
			}
			parsedFloat32, errFloat32 := strconv.ParseFloat(rawFloat32, 32)
			if errFloat32 != nil {
				return errFloat32
			}
			value.SetFloat(parsedFloat32)
			return nil
		case reflect.Float64:
			rawFloat64 := val
			if rawFloat64 == "" {
				rawFloat64 = "0.0"
			}
			parsedFloat64, errFloat64 := strconv.ParseFloat(rawFloat64, 64)
			if errFloat64 != nil {
				return errFloat64
			}
			value.SetFloat(parsedFloat64)
			return nil
		case reflect.String:
			value.SetString(val)
			return nil
		case reflect.Struct:
			switch value.Interface().(type) {
			case time.Time:
				timeFormat := field.Tag.Get("time_format")
				if timeFormat == "" {
					timeFormat = time.RFC3339
				}
				switch tf := strings.ToLower(timeFormat); tf {
				case "unix", "unixnano":
					tv, err := strconv.ParseInt(val, 10, 64)
					if err != nil {
						return err
					}
					d := time.Duration(1)
					if tf == "unixnano" {
						d = time.Second
					}
					t := time.Unix(tv/int64(d), tv%int64(d))
					value.Set(reflect.ValueOf(t))
					return nil
				}
				if val == "" {
					value.Set(reflect.ValueOf(time.Time{}))
					return nil
				}
				l := time.Local
				if isUTC, _ := strconv.ParseBool(field.Tag.Get("time_utc")); isUTC {
					l = time.UTC
				}
				if locTag := field.Tag.Get("time_location"); locTag != "" {
					loc, err := time.LoadLocation(locTag)
					if err != nil {
						return err
					}
					if loc != nil {
						l = loc
					}
				}
				t, err := time.ParseInLocation(timeFormat, val, l)
				if err != nil {
					return err
				}
				value.Set(reflect.ValueOf(t))
				return nil
			}
			return decodeFormJSON(val, value.Addr().Interface())
		case reflect.Map:
			return decodeFormJSON(val, value.Addr().Interface())
		case reflect.Ptr:
			if !value.Elem().IsValid() {
				value.Set(reflect.New(value.Type().Elem()))
			}
			return setWithProperType(val, value.Elem(), field)
		default:
			return errUnknownType
		}
	}
	return errUnknownType
}

func setArray(vals []string, value reflect.Value, field reflect.StructField) error {
	for i, s := range vals {
		err := setWithProperType(s, value.Index(i), field)
		if err != nil {
			return err
		}
	}
	return nil
}

func setSlice(vals []string, value reflect.Value, field reflect.StructField) error {
	slice := reflect.MakeSlice(value.Type(), len(vals), len(vals))
	err := setArray(vals, slice, field)
	if err != nil {
		return err
	}
	value.Set(slice)
	return nil
}

func head(str, sep string) (head string, tail string) {
	idx := strings.Index(str, sep)
	if idx < 0 {
		return str, ""
	}
	return str[:idx], str[idx+len(sep):]
}

func setFormMap(ptr any, form map[string][]string) error {
	el := reflect.TypeOf(ptr).Elem()

	if el.Kind() == reflect.Slice {
		ptrMap, ok := ptr.(map[string][]string)
		if !ok {
			return ErrConvertMapStringSlice
		}
		for k, v := range form {
			ptrMap[k] = v
		}

		return nil
	}

	ptrMap, ok := ptr.(map[string]string)
	if !ok {
		return ErrConvertToMapString
	}
	for k, v := range form {
		ptrMap[k] = v[len(v)-1] // pick last
	}

	return nil
}

